<script lang="ts">import {onMount} from 'svelte';import {listConnections,pipelineErrorMessage,type ConnectionDefinition,type NexetlError}from '$lib/api/pipelines';import PageHeader from '$lib/components/ui/PageHeader.svelte';import Button from '$lib/components/ui/Button.svelte';import Alert from '$lib/components/ui/Alert.svelte';import StatusBadge from '$lib/components/ui/StatusBadge.svelte';let items=$state<ConnectionDefinition[]>([]),loading=$state(true),error=$state('');onMount(async()=>{try{items=(await listConnections()).items}catch(e){error=pipelineErrorMessage(e as NexetlError)}finally{loading=false}})</script>
